async function loadGrowth(){if(!initData())return;try{state.growth=await api("/api/growth/today");renderGrowth();}catch(e){console.warn("Daily growth:",e.message);}}
function renderGrowth(){
 const g=state.growth;if(!g)return;
 const lang=["en","ru","pl","uk"].includes(state.lang)?state.lang:"en",t=growthUi[lang],item=growthChallenges[g.challenge?.id]?.[lang];
 if(!item)return;
 $("#growthEyebrow").textContent=t.eyebrow;$("#growthHeading").textContent=t.heading;$("#growthDate").textContent=t.today;
 $("#growthCategory").textContent=String(g.challenge.category||"").toUpperCase();$("#growthMinutes").textContent=g.challenge.minutes+" "+t.minutes;
 $("#growthTitle").textContent=item[0];$("#growthTask").textContent=item[1];$("#growthXp").textContent="+"+g.challenge.xp+" "+t.xp;
 $("#growthDoneLabel").textContent=g.doneToday?t.done:t.note;$("#growthComplete").textContent=g.doneToday?t.done:t.complete;
 $("#growthComplete").disabled=g.doneToday||!initData();$("#growthNote").textContent=g.doneToday?t.already:t.note;
 $("#growthStreak").textContent=g.streak;$("#growthLevel").textContent=g.level;$("#growthPoints").textContent=g.xp;
 $("#growthStreakLabel").textContent=t.streak;$("#growthLevelLabel").textContent=t.level;$("#growthPointsLabel").textContent=t.points;
 $("#growthNext").textContent=t.next+": "+g.nextLevelXp;
}
$("#growthComplete")?.addEventListener("click",async()=>{
 const btn=$("#growthComplete"),t=growthUi[state.lang]||growthUi.en;if(!state.growth||btn.disabled)return;
 btn.disabled=true;
 try{await api("/api/growth/complete",{method:"POST",body:JSON.stringify({challengeId:state.growth.challenge.id})});await loadGrowth();}
 catch(e){alert(t.error);btn.disabled=false;}
});

