function programTask(day,id){
 const lang=["en","ru","pl","uk"].includes(state.lang)?state.lang:"en";
 if(day<=7){const row=programTasks[day-1];return {title:row[0][["en","ru","pl","uk"].indexOf(lang)],task:row[1][["en","ru","pl","uk"].indexOf(lang)]};}
 const x=extraTasks[(day-8)%extraTasks.length],i=["en","ru","pl","uk"].indexOf(lang);return {title:x[i],task:x[i+4]};
}
async function loadPrograms(){
 if(!initData())return;
 try{const d=await api("/api/growth/programs");programState.progress=d.progress||[];programState.counts=d.counts||{};renderProgram();}
 catch(e){console.warn("Growth programs:",e.message);}
}
function renderProgram(){
 const lang=["en","ru","pl","uk"].includes(state.lang)?state.lang:"en",t=programCopy[lang],id=programState.id,total=id==="reset-7"?7:30,done=new Set(programState.progress.filter(x=>x.program_id===id).map(x=>Number(x.day_number))),count=done.size;
 $("#programEyebrow").textContent=t.eyebrow;$("#programHeading").textContent=t.heading;$("#programIntro").textContent=t.intro;
 $("#program7").textContent=t.week;$("#program30").textContent=t.month;
 document.querySelectorAll("[data-program]").forEach(b=>b.classList.toggle("active",b.dataset.program===id));
 $("#programCount").textContent=count+" / "+total;$("#programPercent").textContent=Math.round(count/total*100)+"% "+t.of;$("#programBar").style.width=(count/total*100)+"%";
 const day=Array.from({length:total},(_,i)=>i+1).find(n=>!done.has(n))||total,task=programTask(day,id);
 $("#programDay").innerHTML='<div class="program-day-top"><span>'+t.day+' '+String(day).padStart(2,"0")+' / '+total+'</span><span>'+(done.has(day)?t.done:'✧')+'</span></div><h3>'+task.title+'</h3><p>'+task.task+'</p><textarea id="programReflection" rows="2" maxlength="1000" placeholder="'+t.reflection+'"></textarea><button class="gold-button wide" id="programComplete" '+(done.has(day)||!initData()?'disabled':'')+'>'+(done.has(day)?t.done:t.complete)+'</button><small class="program-login">'+(!initData()?t.login:(id==="reset-7"?t.reset:t.transform))+'</small>';
 $("#programComplete").onclick=async()=>{const btn=$("#programComplete");btn.disabled=true;try{const reflection=$("#programReflection").value;const r=await api("/api/growth/programs/"+id+"/"+day+"/complete",{method:"POST",body:JSON.stringify({reflection})});programState.progress=programState.progress.filter(x=>!(x.program_id===id&&Number(x.day_number)===day));programState.progress.push(r.progress);programState.counts[id]=r.completed;renderProgram();}catch(e){alert(t.error);btn.disabled=false;}};
}
document.querySelectorAll("[data-program]").forEach(b=>b.onclick=()=>{programState.id=b.dataset.program;renderProgram();});
function renderAcademy(){
 const list=$("#academyList");if(!list)return;const lang=["en","ru","pl","uk"].includes(state.lang)?state.lang:"en",cp=academyCopy[lang],done=new Set(state.academyProgress.filter(x=>x.completed).map(x=>Number(x.month_number))),count=done.size,pct=Math.round(count/12*100);
 $("#academyIntro").textContent=cp.intro;$("#academyPercent").textContent=pct+"%";$("#academyCount").textContent=count+" / 12 "+cp.progress;$("#academyStatus").textContent=count===12?cp.done:cp.intro;$("#academyRing").style.setProperty("--progress",pct+"%");
 list.innerHTML=academyMonths.map((m,i)=>{const n=i+1,completed=done.has(n);return '<article class="academy-month '+(completed?'is-complete':'')+'"><div class="academy-month-top"><span>MONTH '+String(n).padStart(2,"0")+'</span><span class="academy-state">'+(completed?'✓ '+cp.done:'○')+'</span></div><h3>'+m[lang==="en"?0:lang==="ru"?1:lang==="pl"?2:3]+'</h3><p>'+m[lang==="en"?4:lang==="ru"?5:lang==="pl"?6:7]+'</p><div class="academy-task"><b>'+cp.task+'</b><p>'+m[lang==="en"?8:lang==="ru"?9:lang==="pl"?10:11]+'</p></div><button class="academy-toggle" data-month="'+n+'" '+(!initData()?'disabled':'')+'>'+(completed?cp.undo:cp.mark)+'</button></article>';}).join("");
 $("#academyFootnote").textContent=cp.login;
 list.querySelectorAll("[data-month]").forEach(btn=>btn.onclick=async()=>{const n=Number(btn.dataset.month),was=done.has(n);btn.disabled=true;try{const r=await api("/api/academy/progress/"+n,{method:"POST",body:JSON.stringify({completed:!was})});state.academyProgress=state.academyProgress.filter(x=>Number(x.month_number)!==n);state.academyProgress.push(r.progress);renderAcademy();}catch(e){alert(e.message||cp.login);btn.disabled=false;}});
}
